fn main() {
    let mut output = String::from(
        "// Generated by `cargo run -p isct-core --features ts --example export-types`. Do not edit.\n\n",
    );
    for declaration in isct_core::contracts::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    for declaration in isct_core::study_profile::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    for declaration in isct_core::school_service::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    for declaration in isct_core::schedule::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    for declaration in isct_core::workspace::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    for declaration in isct_core::course_query::declarations() {
        output.push_str("export ");
        output.push_str(&declaration);
        output.push_str("\n\n");
    }
    output.push_str("export const DATA_POLICY: DataPolicy = ");
    output.push_str(
        &serde_json::to_string_pretty(&isct_core::contracts::data_policy())
            .expect("serialize data policy"),
    );
    output.push_str(";\n\nexport const COURSE_FILE_POLICY: CourseFilePolicy = ");
    output.push_str(
        &serde_json::to_string_pretty(&isct_core::contracts::course_file_policy())
            .expect("serialize course file policy"),
    );
    output.push_str(";\n");
    output.push_str("\nexport const COURSE_PALETTE = ");
    output.push_str(
        &serde_json::to_string(&isct_core::schedule::COURSE_PALETTE)
            .expect("serialize course palette"),
    );
    output.push_str(" as const;\n");
    output.push_str("\nexport const DEFAULT_TEACHING_PERIODS: TeachingPeriod[] = ");
    output.push_str(
        &serde_json::to_string_pretty(&isct_core::schedule::default_teaching_periods())
            .expect("serialize default teaching periods"),
    );
    output.push_str(";\n");
    output.push_str("\nexport const EMPTY_WORKSPACE: Workspace = ");
    output.push_str(
        &serde_json::to_string_pretty(
            &isct_core::data::initial_workspace(
                chrono::NaiveDate::from_ymd_opt(2026, 4, 1).expect("fixture date"),
                "preview-device",
                "2026-04-01T00:00:00.000Z",
            )
            .expect("valid initial workspace"),
        )
        .expect("serialize empty workspace"),
    );
    output.push_str(";\n");
    output.push_str("\nexport const PUBLIC_DATA_INDEX = ");
    output.push_str(
        &serde_json::to_string(isct_core::reference_refresh::PUBLIC_INDEX)
            .expect("serialize public index"),
    );
    output.push_str(";\n");
    output.push_str("\nexport const REFERENCE_KINDS = ");
    output.push_str(
        &serde_json::to_string(&isct_core::reference_refresh::REFERENCE_KINDS)
            .expect("serialize reference kinds"),
    );
    output.push_str(" as const;\n");
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../apps/desktop/src/generated/persistence.ts");
    std::fs::create_dir_all(path.parent().expect("generated directory"))
        .expect("create generated directory");
    std::fs::write(path, output).expect("write generated TypeScript contracts");
}
